import {Icon} from '@ui-kitten/components';
import {Text, TouchableOpacity, View} from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';
import {useEffect, useState} from 'react';
import {TaskGroup} from '../../../../../model/interface/dashboard.interface';
import TableCM from '../../../../components/Table';
import {styles} from './styles';
import {Font} from '../../../../../constants';
import {isEmpty} from 'lodash';
import {LISTPRIORITYCOLOR} from './helper';
type Props = {
  item: TaskGroup;
  type?: string | null;
};

const TableTaskCard = ({item, type}: Props) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const rotation = useSharedValue(0);
  const [dataTable, setDataTable] = useState<any>();

  const toggleExpand = () => {
    setIsExpanded(!isExpanded);
    rotation.value = withTiming(isExpanded ? 0 : 90, {duration: 300});
  };
  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{rotate: `${rotation.value}deg`}],
    };
  });
  function formatDateToGMT7(input: string) {
    if (isEmpty(input)) return '';
    const utcDate = new Date(input);

    // Cộng thêm 7 tiếng
    const gmt7Timestamp = utcDate.getTime() + 7 * 60 * 60 * 1000;
    const gmt7Date = new Date(gmt7Timestamp);

    const day = String(gmt7Date.getDate()).padStart(2, '0');
    const month = String(gmt7Date.getMonth() + 1).padStart(2, '0');
    const year = gmt7Date.getFullYear();

    const hours = String(gmt7Date.getHours()).padStart(2, '0');
    const minutes = String(gmt7Date.getMinutes()).padStart(2, '0');

    return `${day}/${month}/${year} ${hours}:${minutes}`;
  }
  function daysUntil(inputDate: string) {
    if (isEmpty(inputDate)) return '';
    const now: any = new Date();
    const target: any = new Date(inputDate);
    now.setHours(0, 0, 0, 0);
    target.setHours(0, 0, 0, 0);

    const diffTime = target - now;
    const diffDays = Math.abs(Math.ceil(diffTime / (1000 * 60 * 60 * 24)));

    return diffDays;
  }
  const transformData = () => {
    const Priorities = ['#FF4930', '#CA8A04', '#16A34A', '#00204D47'];

    const newData = item.task.map((_, index) => {
      const iconPriority = !isEmpty(_.priority) ? (
        <Icon
          name="flag"
          width={22}
          height={22}
          fill={LISTPRIORITYCOLOR[index]}
        />
      ) : (
        ''
      );
      return {
        STT: index + 1,
        'HM.board.table-order': index + 1,
        'HM.board.table-name': _.name,
        'HM.board.table-tag': _.tags,
        'HM.board.table-dayExpired':
          type == 'missed' ? formatDateToGMT7(_.dueDate) : '',
        'HM.board.table-overdue': type == 'missed' ? daysUntil(_.dueDate) : '',
        'HM.board.table-priority': iconPriority,
        'HM.board.table-subtask': _.numberSubtasks,
        'HM.board.table-checklist': _.numberChecklists,
        'HM.board.table-fileAttach': _.numberAttachments,
        'HM.board.table-comment': _.numberComments,
      };
    });
    setDataTable(newData);
  };
  useEffect(() => {
    transformData();
  }, [item]);
  return (
    <View style={styles.container}>
      <TouchableOpacity onPress={toggleExpand} style={styles.header}>
        <Animated.View style={[styles.arrow, animatedStyle]}>
          <Icon name={'arrow-right'} fill={'grey'} width={24} height={24} />
        </Animated.View>
        <Text style={styles.title}>{item.listTaskName}</Text>
      </TouchableOpacity>
      {isExpanded && (
        <View style={styles.content}>
          <TableCM
            styleTextHeader={{
              fontFamily: Font.InterSemiBold600,
              color: 'rgba(0, 32, 77, .9)',
            }}
            styleHeader={{
              backgroundColor: '#f1f1f1',
            }}
            tableData={dataTable}
            tableHeaders={[
              'HM.board.table-order',
              'HM.board.table-name',
              'HM.board.table-tag',
              'HM.board.table-dayExpired',
              'HM.board.table-overdue',
              'HM.board.table-priority',
              'HM.board.table-subtask',
              'HM.board.table-checklist',
              'HM.board.table-fileAttach',
              'HM.board.table-comment',
            ]}
          />
        </View>
      )}
    </View>
  );
};

export default TableTaskCard;
