import {Dimensions, Platform, ScrollView, Text, View} from 'react-native';
import TextCM from '../../../components/Text';
import {PieChart} from 'react-native-gifted-charts';
import {styles} from './styles';
import {StatusGroup} from '../../../../model/interface/dashboard.interface';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../constants';
import {Text as SvgText} from 'react-native-svg';
type Props = {
  status: StatusGroup[];
};

const DashboardPieChart = ({status}: Props) => {
  const {t} = useTranslation();
  const screenWidth = Dimensions.get('window').width;
  const ChartColor: {[key: string]: string} = {
    todo: '#00A3FF',
    processing: '#FF69B4',
    approved: '#943CDD',
    completed: '#90EE90',
  };
  const transformData = (status: StatusGroup[]) => {
    const dataFiltered = status
      .map(item => {
        const color = ChartColor[item.status];
        const value = ['todo', 'processing', 'approved', 'completed'].includes(
          item.status,
        )
          ? item.taskCount
          : 0;
        return {
          value,
          text: t(`HM.board.status-${item.status}`),
          color: ChartColor[item.status],
          externalLabelComponent: () => {
            return <SvgText>{value}</SvgText>;
          },
        };
      })
      .filter(item => item.value > 0);
    return dataFiltered;
  };
  let pieData = transformData(status);
  const renderDot = (color: string) => {
    return (
      <View
        style={{
          height: 10,
          width: 10,
          borderRadius: 5,
          backgroundColor: color,
          marginRight: 10,
        }}
      />
    );
  };

  const renderItemDescription = (item: any) =>
    item.value ? (
      <View
        key={item.text}
        style={{
          flexDirection: 'row',
          alignItems: 'center',
          padding: 5,
        }}>
        {renderDot(item.color)}
        <Text style={{color: item.color}}>{`${item.text}: ${item.value}`}</Text>
      </View>
    ) : null;
  const renderDescription = (pieData: any[]) => {
    // 1) Chia thành mảng columns, mỗi column là mảng 1 hoặc 2 phần tử
    const columns: any[][] = pieData.reduce((acc, item, idx) => {
      if (idx % 2 === 0) {
        // bắt đầu cột mới
        acc.push([item]);
      } else {
        // thêm vào column cuối cùng
        acc[acc.length - 1].push(item);
      }
      return acc;
    }, [] as any[][]);

    return (
      <ScrollView horizontal style={{marginTop: 20}}>
        <View style={{flexDirection: 'row'}}>
          {columns.map((col, colIndex) => (
            <View
              key={colIndex}
              style={{
                flexDirection: 'column',
                justifyContent: 'space-between',
                marginRight: 10, // khoảng cách giữa các cột
              }}>
              {/* Hàng trên */}
              {col[0] && renderItemDescription(col[0])}
              {/* Hàng dưới (nếu có) */}
              {col[1] && renderItemDescription(col[1])}
            </View>
          ))}
        </View>
      </ScrollView>
    );
  };
  return (
    <View style={styles.container}>
      <TextCM style={{fontSize: 18, fontFamily: Font.InterBold700}}>
        Tỉ lệ task theo trạng thái
      </TextCM>
      <View
        style={{
          width: screenWidth, // Chiều rộng bằng màn hình
          height: screenWidth - 40, // Chiều cao bằng màn hình để tạo hình vuông
          justifyContent: 'center', // Căn giữa theo chiều dọc
          alignItems: 'center', // Căn giữa theo chiều ngang
          backgroundColor: '#fff', // Nền trắng (có thể thay đổi tùy ý)
          overflow: 'hidden',
        }}>
        {/* <TextCM>Biểu đồ 2</TextCM> */}
        <PieChart
          data={pieData}
          // radius={80}
          // showText={true}
          textColor={'black'}
          labelsPosition={'outward'}
          showTooltip={true}
          // showValuesAsTooltipText={true}
          // semiCircle={true}
          // showText
          showExternalLabels={Platform.OS == 'ios' ? true : true}
          shadow={true}
          // focusedPieIndex={2}
          strokeWidth={0}
          // textColor={'black'}
          labelLineConfig={{
            color: 'black',
            // labelComponentHeight: Platform.OS == 'ios' ? -20 : 20,
            // labelComponentHeight: 20,
            // labelComponentWidth: 50,
            avoidOverlappingOfLabels: true,
            // tailLength: 5,
            thickness: 1,
          }}
          // externalLabelComponent={(a, b) => {
          //   //   console.log({a, b});
          //   //   console.log(a?.externalLabelComponent);
          //   //   console.log(`${a?.text}: ${a?.value}`);
          //   return ;
          // }}
        />
      </View>
      {renderDescription(pieData)}
    </View>
  );
};

export default DashboardPieChart;
