import {ScrollView, Text, View} from 'react-native';
import {PieChart} from 'react-native-gifted-charts';
import {Organization} from '../../../../model/interface/dashboard.interface';
import {useEffect, useState} from 'react';
import {Font} from '../../../../constants';
import TextCM from '../../../components/Text';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
type Props = {
  organization: Organization[];
};
type PieData = {
  name: string;
  value: number;
  color: string;
};
const DashboardDonut = ({organization}: Props) => {
  const inset = useSafeAreaInsets();
  const [totalTask, setTotalTask] = useState<number>(0);
  const [pieData, setPieData] = useState<PieData[]>([]);
  const getRandomColor = () => {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  };
  const tranformData = (organization: Organization[]) => {
    const initColor = ['#00A3FF', '#FF69B4', '#943CDD', '#90EE90'];
    let totalTask = 0;
    const data = organization
      .sort((a, b) => b.taskCountOrg - a.taskCountOrg)
      .map((item, index) => {
        const value = item.taskCountOrg;
        const name = item.name;
        totalTask += item.taskCountOrg;
        return {
          value,
          color: index < 3 ? initColor[index] : getRandomColor(),
          name,
        };
      });
    setTotalTask(totalTask);
    setPieData(data);
  };
  useEffect(() => {
    tranformData(organization);
  }, [organization]);
  const renderDot = (color: string) => {
    return (
      <View
        style={{
          height: 10,
          width: 10,
          borderRadius: 5,
          backgroundColor: color,
          marginRight: 10,
        }}
      />
    );
  };

  const renderItemDescription = (item: any) => (
    <View
      key={item.text}
      style={{
        flexDirection: 'row',
        alignItems: 'center',
        padding: 5,
      }}>
      {renderDot(item.color)}
      <Text style={{color: item.color}}>{`${item.name}: ${item.value}`}</Text>
    </View>
  );
  const renderDescription = (pieData: any[]) => {
    // 1) Chia thành mảng columns, mỗi column là mảng 1 hoặc 2 phần tử
    const columns: any[][] = pieData.reduce((acc, item, idx) => {
      if (idx % 2 === 0) {
        // bắt đầu cột mới
        acc.push([item]);
      } else {
        // thêm vào column cuối cùng
        acc[acc.length - 1].push(item);
      }
      return acc;
    }, [] as any[][]);

    return (
      <ScrollView horizontal style={{marginTop: 20}}>
        <View style={{flexDirection: 'row'}}>
          {columns.map((col, colIndex) => (
            <View
              key={colIndex}
              style={{
                flexDirection: 'column',
                justifyContent: 'space-between',
                marginRight: 10, // khoảng cách giữa các cột
              }}>
              {/* Hàng trên */}
              {col[0] && renderItemDescription(col[0])}
              {/* Hàng dưới (nếu có) */}
              {col[1] && renderItemDescription(col[1])}
            </View>
          ))}
        </View>
      </ScrollView>
    );
  };
  return (
    <View
      style={{
        backgroundColor: '#FFF',
        padding: 20,
        alignItems: 'center',
        borderRadius: 10,
        margin: 10,
        marginBottom: inset.bottom,
        shadowColor: '#000',
        shadowOffset: {
          width: 0,
          height: 2,
        },
        shadowOpacity: 0.23,
        shadowRadius: 2.62,
        elevation: 4,
        overflow: 'hidden',
      }}>
      <TextCM style={{fontSize: 16, fontFamily: Font.InterBold700}}>
        {'Tổng số task theo phòng ban'}
      </TextCM>
      <View style={{padding: 20, alignItems: 'center'}}>
        <PieChart
          data={pieData}
          donut
          radius={90}
          innerRadius={60}
          innerCircleColor={'#fff'}
          centerLabelComponent={() => {
            return (
              <View style={{justifyContent: 'center', alignItems: 'center'}}>
                <Text
                  style={{
                    fontSize: 22,
                    color: 'black',
                    fontFamily: Font.InterBold700,
                  }}>
                  {totalTask}
                </Text>
                <Text style={{fontSize: 14, color: 'black'}}>
                  {'Tổng cộng'}
                </Text>
              </View>
            );
          }}
        />
      </View>
      {renderDescription(pieData)}
    </View>
  );
};

export default DashboardDonut;
